@app.cell(hide_code=True)
def _(mo):
    mo.Html('<section class="ph-lesson"><a href="https://www.pianohof.de/"><img class="logo" src="data:image/svg+xml;base64," alt="PIANOHOF" width="300" height="52"></a><p><small>Juri Enes · Klaviernotizen</small></p><h1>Schwebungen hören: Gleiche Cent, anderes Tempo</h1></section><section class="ph-lesson"><p>Zwei fast gleich hohe Töne können gemeinsam regelmäßig lauter und leiser werden. Dieses Pulsieren heißt Schwebung. Es lässt sich leichter verstehen, wenn man zwei Fragen trennt: Wie weit liegen die Tonhöhen musikalisch auseinander, und wie oft pro Sekunde verändert sich die gemeinsame Lautstärke? Die erste Frage können wir in Cent beantworten, die zweite mit einer Frequenzdifferenz in Hertz. Beides beschreibt denselben Vergleich aus unterschiedlicher Sicht.</p><h2>Zuerst mit zwei einfachen Tönen hören</h2><p>Die Hörübung erzeugt zwei reine Sinustöne. Wähle zunächst 440 Hertz und vier Cent Abweichung. Starte die Wiedergabe bei niedriger Lautstärke; sie beginnt niemals automatisch. Beide Signale werden vor der Ausgabe zusammengemischt. Deshalb gelangen sie gemeinsam an jedes Ohr. Ein Ton nur links und der andere nur rechts wäre ein anderes Experiment. Nach einer Änderung entsteht eine neue zwölf Sekunden lange Aufnahme, die du erneut starten kannst.</p><p>Höre einige Sekunden auf das wiederkehrende Anschwellen. Zähle die deutlichen Lautstärkemaxima in einem mittleren Abschnitt der Aufnahme. Anfang und Ende werden kurz weich ein- und ausgeblendet und eignen sich deshalb weniger zum Zählen. Die Wellenhüllkurve unter dem Rechner zeigt das entsprechende Muster. Sie ist auf sechs Sekunden begrenzt; die Aufnahme dauert länger. Sichtbare und hörbare Perioden beziehen sich auf dieselben eingestellten Frequenzen.</p></section>')
    return 


@app.cell(hide_code=True)
def _(mo):
    reference = mo.ui.dropdown(options={"220 Hz · tiefer":220, "440 Hz · mittlerer Vergleich":440, "880 Hz · höher":880}, value="440 Hz · mittlerer Vergleich", label="Bezugsfrequenz", full_width=True)
    unit = mo.ui.dropdown(options=["Cent", "Hertz"], value="Cent", label="Abweichung angeben in", full_width=True)
    offset = mo.ui.slider(start=-12, stop=12, step=0.5, value=4, show_value=True, include_input=True, label="Abweichung (gewählte Einheit)", full_width=True)
    mo.vstack([mo.Html('<section class="ph-lesson"><h2>Dein Hörvergleich</h2><p>Geringe Lautstärke einstellen. Änderungen erzeugen eine neue Aufnahme; starte sie selbst.</p></section>'), mo.Html('<div class="ph-field">{reference}</div>'.format(reference=reference)), mo.Html('<div class="ph-field">{unit}</div>'.format(unit=unit)), mo.Html('<div class="ph-field">{offset}</div>'.format(offset=offset))])
    return reference, unit, offset


@app.cell(hide_code=True)
def _(reference, unit, offset, math, io, wave, struct, base64, mo):
    f1 = float(reference.value)
    amount = float(offset.value)
    f2 = f1 * 2 ** (amount / 1200) if unit.value == "Cent" else f1 + amount
    beat = abs(f2 - f1)
    cents = 1200 * math.log2(f2 / f1)
    period_text = "keine periodische Schwebung" if beat < 1e-10 else f"{1/beat:.3f} Sekunden"
    _points = " ".join(f"{50+i:.1f},{115-75*abs(math.cos(math.pi*beat*i/100)):.2f}" for i in range(601))
    _svg = f'<svg viewBox="0 0 700 155" role="img" aria-label="Betrag der Amplitudenhüllkurve über sechs Sekunden"><path d="M50 30V115H660" fill="none" stroke="#f6e69480"/><polyline points="{_points}" fill="none" stroke="#ffeab6" stroke-width="2"/><text x="50" y="143" fill="#f6e694" font-size="15">0 s</text><text x="620" y="143" fill="#f6e694" font-size="15">6 s</text></svg>'
    _rate = 22050
    _samples = bytearray()
    for _i in range(12 * _rate):
        _t = _i / _rate
        _fade = min(1.0, _t / .02, (12 - _t) / .02)
        _sample = .09 * _fade * (math.sin(2*math.pi*f1*_t) + math.sin(2*math.pi*f2*_t))
        _samples.extend(struct.pack('<h', round(32767*_sample)))
    _buffer = io.BytesIO()
    with wave.open(_buffer, 'wb') as _wav:
        _wav.setnchannels(1)
        _wav.setsampwidth(2)
        _wav.setframerate(_rate)
        _wav.writeframes(_samples)
    _audio = base64.b64encode(_buffer.getvalue()).decode()
    _markup = f'<section class="ph-lesson ph-result"><dl><dt>Erster Ton</dt><dd>{f1:.3f} Hz</dd><dt>Zweiter Ton</dt><dd>{f2:.3f} Hz</dd><dt>Abstand</dt><dd>{cents:.3f} Cent</dd><dt>Schwebungsfrequenz</dt><dd>{beat:.3f} Hz</dd><dt>Zeit zwischen Maxima</dt><dd>{period_text}</dd></dl><audio controls preload="none" aria-label="Zwei zusammengemischte Sinustöne, zwölf Sekunden"><source src="data:audio/wav;base64,{_audio}" type="audio/wav"></audio><p><small>Mono · beide Töne gemeinsam · 12 Sekunden · keine automatische Wiedergabe</small></p>{_svg}<p><small>Betrag der Hüllkurve. Bei gleichen Frequenzen bleibt sie konstant. Ein- und Ausblenden der Aufnahme sind hier nicht dargestellt.</small></p></section>'
    mo.Html(_markup)
    return f1, f2, beat, cents


@app.cell(hide_code=True)
def _(mo):
    mo.Html('<section class="ph-lesson"><figure><img src="https://pianohof-berlin.github.io/juri-enes-pedalwechsel/fluegelmechanik-auf-werkbank.jpg" alt="Flügelmechanik auf einer Werkbank bei PIANOHOF" width="1500" height="1500" loading="lazy"><figcaption>Werkstattaufnahme von PIANOHOF: die Mechanik eines Flügels. Keine Messaufnahme der Hörübung.</figcaption></figure></section><section class="ph-lesson"><h2>Hertz zählen Veränderungen pro Sekunde</h2><p>Bei 440 und 441 Hertz beträgt die Differenz genau ein Hertz. Die gemeinsame Lautstärke erreicht daher ungefähr einmal pro Sekunde ein Maximum. Bei 440 und 442 Hertz sind es zwei Maxima pro Sekunde. Für diese zwei gleich lauten, nahe beieinanderliegenden Sinustöne gilt: Schwebungsfrequenz gleich Betrag der Frequenzdifferenz. Das Vorzeichen verrät die Richtung der Verstimmung, aber nicht das Tempo der Schwebung.</p><h2>Cent vergleichen ein Verhältnis</h2><p>Ein gleichstufiger Halbton umfasst 100 Cent, eine Oktave 1200 Cent. Vier Cent bedeuten deshalb an jeder Stelle denselben kleinen Anteil eines Halbtons. Die zweite Frequenz ergibt sich hier aus f₂ = f₁ × 2^(Cent/1200). Das ist eine Verhältnisrechnung. Vier Cent über 440 Hertz entsprechen ungefähr 441,018 Hertz. Vier Cent über 880 Hertz ergeben ungefähr 882,036 Hertz. Das musikalische Verhältnis bleibt gleich; die Differenz in Hertz verdoppelt sich.</p><h2>Drei Lagen direkt vergleichen</h2><p>Lass die Abweichung bei vier Cent stehen und wechsle zwischen 220, 440 und 880 Hertz. Die berechneten Schwebungsfrequenzen liegen ungefähr bei 0,509, 1,018 und 2,036 Hertz. In der höheren Lage pulsiert derselbe Cent-Abstand schneller. Vergleiche anschließend mit der Einstellung „Hertz“: Eine feste Abweichung von einem Hertz ergibt in allen drei Lagen eine Schwebung pro Sekunde. Ihr Abstand in Cent ist dagegen unterschiedlich groß.</p></section>')
    return 


@app.cell(hide_code=True)
def _(mo):
    mo.Html('<section class="ph-lesson"><figure><img src="https://pianohof-berlin.github.io/juri-enes-pedalwechsel/klaviermechanik-im-gehaeuse.jpg" alt="Klaviermechanik im geöffneten Gehäuse" width="1500" height="1500" loading="lazy"><figcaption>Klaviermechanik im geöffneten Gehäuse. Die Aufnahme dient der instrumentalen Einordnung.</figcaption></figure></section><section class="ph-lesson"><p>Probiere auch eine negative Abweichung. Bei gleichem Betrag in Hertz bleibt das Schwebungstempo gleich, gleichgültig, ob der zweite Ton höher oder tiefer liegt. Bei exakt plus und minus vier Cent sind die Frequenzdifferenzen nur annähernd gleich: Die Umrechnung ist exponentiell. Der Rechner zeigt die kleine Asymmetrie. Allein aus dem Pulsieren lässt sich deshalb weder die sichere Richtung einer Verstimmung noch ihr Cent-Wert ohne Bezugsfrequenz ablesen.</p><h2>Was das Modell über ein Klavier aussagt</h2><p>Ein Klavierton enthält viele Teiltöne und klingt nach dem Anschlag ab. Bei vielen Tasten schwingen mehrere Saiten gemeinsam. Außerdem liegen die höheren Teiltöne einer realen Saite wegen ihrer Steifigkeit nicht genau bei ganzzahligen Vielfachen der Grundfrequenz. Dadurch können mehrere Schwebungsmuster gleichzeitig entstehen. Die einfache Sinusübung isoliert einen Zusammenhang; sie bildet weder einen vollständigen Klavierklang noch eine fertige Stimmung nach.</p><p>Die beiden Werkstattaufnahmen zeigen reale Klaviermechaniken. Sie veranschaulichen den instrumentalen Zusammenhang, dokumentieren jedoch keine Messung der hier erzeugten Signale. Auch das ergänzende Video über Polyesterlack zeigt Oberflächenarbeit und keine Schwebungsdiagnose. Für das Hören der berechneten Beispiele dienen ausschließlich die Audioplayer dieser Übung.</p><h2>Das Ergebnis sinnvoll nutzen</h2><p>Ein nützlicher Abschluss besteht darin, zuerst eine Vorhersage zu formulieren: Wird das Pulsieren beim Oktavieren schneller, wenn ich Cent konstant halte? Prüfe sie am Rechner und anschließend mit dem Ohr. Wiederhole den Vergleich bei konstanter Hertz-Differenz. Wer den Unterschied erklären kann, versteht mehr als einen einzelnen Zahlenwert. Diese Übung ist eine Hilfe beim bewussten Zuhören; sie ist keine Anleitung zum selbstständigen Verstellen von Stimmwirbeln.</p></section>')
    return 


