@app.cell(hide_code=True)
def _(mo, restart):
    _attempt = restart.value
    questions = [('440 und 441 Hz: Wie schnell pulsiert die Lautstärke?', ['Einmal pro Sekunde', '100-mal pro Sekunde', '441-mal pro Sekunde'], 0, 'Der Betrag der Differenz ist 1 Hz.'), ('440 und 442 Hz: Welche Schwebungsfrequenz ergibt sich?', ['0,5 Hz', '2 Hz', '882 Hz'], 1, '442 − 440 = 2 Hz; das sind zwei Maxima pro Sekunde.'), ('Die Bezugshöhe verdoppelt sich, vier Cent bleiben konstant. Was geschieht?', ['Das Tempo bleibt gleich', 'Das Tempo halbiert sich', 'Das Tempo verdoppelt sich'], 2, 'Bei gleichem Frequenzverhältnis verdoppelt sich auch die Differenz in Hertz.'), ('Ein Hertz Unterschied bleibt konstant. Was geschieht beim Wechsel der Lage?', ['Das Pulsieren bleibt bei 1 Hz', 'Es verdoppelt sich immer', 'Es verschwindet'], 0, 'Die feste Differenz bestimmt das Tempo; ihr Cent-Wert ändert sich.'), ('Wie viele Cent umfasst eine gleichstufige Oktave?', ['12', '100', '1200'], 2, 'Zwölf Halbtöne zu jeweils 100 Cent ergeben 1200 Cent.'), ('Zwei Töne haben exakt dieselbe Frequenz. Was zeigt das Modell?', ['Eine Schwebung pro Sekunde', 'Keine periodische Schwebung', 'Unendlich schnelle Schwebungen'], 1, 'Die Frequenzdifferenz ist null. Die gemeinsame Schwingung pulsiert hier nicht.'), ('Kann man allein aus einer Schwebung von 1 Hz sagen, welcher Ton zu hoch liegt?', ['Ja, immer der leisere', 'Ja, immer der zweite', 'Nein'], 2, 'Der Betrag der Differenz enthält keine Richtungsinformation.'), ('Warum ist die Übung keine vollständige Klavierstimmung?', ['Ein Klavier hat Teiltöne, mehrere Saiten und Inharmonizität', 'Ein Klavier besitzt keine Schwebungen', 'Cent gelten nur für Computer'], 0, 'Das Modell verwendet nur zwei gleich laute Sinustöne und isoliert einen Zusammenhang.')]
    _inputs = {f"q{i+1}": mo.ui.dropdown(options=q[1], value=None, label=f"{i+1}. {q[0]}", full_width=True) for i,q in enumerate(questions)}
    _layout = mo.Html('<section class="ph-lesson">'+''.join('<div class="ph-field">{q'+str(i+1)+'}</div>' for i in range(8))+'</section>').batch(**_inputs)
    quiz = mo.ui.form(_layout, bordered=False, submit_button_label="Antworten prüfen", show_clear_button=False)
    mo.vstack([mo.Html('<section class="ph-lesson"><h2>Acht Fragen zur Selbstkontrolle</h2><p>Wähle je eine Antwort. Nach dem Prüfen erhältst du zu jeder Frage eine Erklärung.</p></section>'), quiz, restart])
    return questions, quiz


@app.cell(hide_code=True)
def _(quiz, questions, html, mo):
    if quiz.value is None:
        _feedback = '<p>Die Erklärungen erscheinen nach „Antworten prüfen“.</p>'
    else:
        _score = sum(quiz.value.get(f"q{i+1}") == q[1][q[2]] for i,q in enumerate(questions))
        _feedback = f'<h2>{_score} von 8 richtig</h2>'
        for _i,_q in enumerate(questions):
            _answer = quiz.value.get(f"q{_i+1}")
            _correct = _answer == _q[1][_q[2]]
            _status = 'Richtig' if _correct else ('Noch nicht beantwortet' if _answer is None else 'Noch einmal überlegen')
            _feedback += f'<div class="feedback"><strong>{_i+1}. {html.escape(_status)}</strong><p>{html.escape(_q[3])}</p></div>'
    mo.Html('<section class="ph-lesson">'+_feedback+'</section>')
    return 


